css:
.ksa-inv { font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif; color:#2b2b2b; font-size:12px; }
.ksa-inv table { border-collapse: collapse; }
.ksa-head { display:flex; justify-content:space-between; align-items:flex-start; padding-bottom:12px; border-bottom:3px solid #16606b; }
.ksa-logo { max-height:64px; max-width:190px; margin-bottom:6px; }
.ksa-company-name { font-size:18px; font-weight:700; color:#16606b; }
.ksa-meta { color:#5a6a6c; font-size:11px; margin-top:4px; line-height:1.5; }
.ksa-title { text-align:right; }
.ksa-title .en { font-size:22px; font-weight:700; color:#16606b; letter-spacing:1px; }
.ksa-title .ar { font-size:17px; color:#333; }
.ksa-strip { display:flex; background:#f1f6f7; border-radius:6px; margin:14px 0; padding:9px 14px; }
.ksa-strip .cell { flex:1; }
.ksa-strip .lbl { font-size:9.5px; color:#7f9295; text-transform:uppercase; letter-spacing:.4px; }
.ksa-strip .val { font-size:13px; font-weight:600; margin-top:2px; }
.ksa-parties { display:flex; gap:12px; margin:0 0 14px; }
.ksa-party { flex:1; border:1px solid #e1e8e9; border-radius:6px; padding:10px 12px; }
.ksa-party h4 { margin:0 0 6px; font-size:10.5px; color:#16606b; text-transform:uppercase; letter-spacing:.4px; border-bottom:1px solid #eef2f3; padding-bottom:4px; }
.ksa-party .nm { font-weight:700; font-size:13px; }
.ksa-party div { line-height:1.5; }
.ksa-items { width:100%; margin-top:2px; font-size:11px; }
.ksa-items thead th { background:#16606b; color:#fff; padding:8px 6px; text-align:center; font-weight:600; line-height:1.25; }
.ksa-items tbody td { padding:7px 6px; border-bottom:1px solid #eceff0; vertical-align:top; }
.ksa-items tbody tr:nth-child(even) { background:#f8fafa; }
.ksa-items .l { text-align:left; }
.ksa-items .r { text-align:right; }
.ksa-items .c { text-align:center; }
.ksa-items .desc-sub { color:#8a9698; font-size:9.5px; margin-top:2px; }
.ksa-bottom { display:flex; justify-content:space-between; margin-top:16px; align-items:flex-start; }
.ksa-qr { text-align:center; }
.ksa-qr img { width:180px; height:180px; border:1px solid #e1e8e9; border-radius:6px; padding:4px; }
.ksa-qr .cap { font-size:9.5px; color:#7f9295; margin-top:5px; }
.ksa-totals { width:280px; }
.ksa-totals table { width:100%; font-size:12px; }
.ksa-totals td { padding:6px 10px; }
.ksa-totals .lbl { color:#555; }
.ksa-totals .amt { text-align:right; font-weight:600; white-space:nowrap; }
.ksa-totals .sub td { border-bottom:1px solid #eceff0; }
.ksa-totals .grand td { background:#16606b; color:#fff; font-weight:700; font-size:14px; }
.ksa-totals .grand td:first-child { border-radius:5px 0 0 5px; }
.ksa-totals .grand td:last-child { border-radius:0 5px 5px 0; color:#fff; }
.ksa-words { margin-top:12px; font-size:11px; color:#444; background:#f8fafa; border-radius:5px; padding:7px 12px; }
.ksa-foot { margin-top:18px; border-top:1px solid #e1e8e9; padding-top:9px; font-size:10px; color:#8a9698; text-align:center; line-height:1.5; }
